import json, collections
for name in ('fixtures/target_accounts.json','fixtures/second_list.json'):
    a=json.load(open(name))
    print('=====',name)
    blanks=[ (i,r) for i,r in enumerate(a) if not r.get('company_id') ]
    print('rows with falsy/missing company_id:', len(blanks))
    for i,r in blanks: print('   idx',i, json.dumps(r))
    pos=collections.defaultdict(list)
    for i,r in enumerate(a): pos[str(r['company_id'])].append(i)
    for ps in (10,25,100):
        kept=[]; seen_global=collections.Counter()
        survivors=collections.defaultdict(int)
        for s in range(0,len(a),ps):
            page=a[s:s+ps]; seen=set()
            for r in page:
                c=str(r['company_id'])
                if c in seen: continue
                seen.add(c); kept.append(r); survivors[c]+=1
        extra={k:v for k,v in survivors.items() if v>1}
        print(f' page_size={ps}: rows kept={len(kept)} deliverables={len(kept)*4} distinct={len(survivors)} company_ids surviving twice+: {extra}')
EOF

